private void scheduleBonemeal(ServerLevel level, BlockPos target) {
		MinecraftServer server = level.getServer();
		FakePlayer fakePlayer = FakePlayerFactory.getMinecraft(level);
		server.schedule(new TickTask(server.getTickCount(), () -> {
			//We need to use a tick task so that plants that grow into tall variants don't just break upon growth
			for (int i = 0; i < 15; i++)
				BoneMealItem.applyBonemeal(new ItemStack(Items.BONE_MEAL), level, target, fakePlayer);
		}));
		level.levelEvent(LevelEvent.PARTICLES_AND_SOUND_PLANT_GROWTH, target, 15); // Bonemeal particles
	}

@SubscribeEvent
        public static void onContainerClose(PlayerContainerEvent.Close event) {
            // reopen the main secstation window if closing a test-mode hacking window
            if (event.getEntity() instanceof ServerPlayer player && event.getContainer() instanceof SecurityStationHackingMenu menu) {
                SecurityStationBlockEntity teSS = menu.blockEntity;
                if (teSS.getSimulationController() != null && teSS.getSimulationController().isJustTesting()) {
                    MinecraftServer server = player.getServer();
                    if (server != null) {
                        // deferring is important to avoid infinite close/open loop
                        server.tell(new TickTask(server.getTickCount(), () -> player.openMenu(teSS, teSS.getBlockPos())));
                    }
                }
            }
        }

private void onLevelTick(LevelTickEvent.Post event) {
		if (event.getLevel().isClientSide() || !(event.getLevel() instanceof ServerLevel serverLevel) || pendingTickTasks.isEmpty()) {
			return;
		}

		Iterator<TickTask> it = pendingTickTasks.iterator();

		while (it.hasNext()) {
			TickTask tickTask = it.next();
			if (tickTask.getTick() <= serverLevel.getServer().getTickCount()) {
				tickTask.run();
				it.remove();
			}
		}
	}

