@SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }

@Override
    public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        super.onResolveEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver);
        int ticksToRewind = getRewindTicks(spellStats);
        Entity entity = rayTraceResult.getEntity();
        if (!entity.getType().is(EntityTags.REWIND_BLACKLIST) && entity instanceof IRewindable rewindable && !rewindable.isRewinding()) {
            var delayEvent = new DelayedSpellEvent(ticksToRewind, rayTraceResult, world, resolver);
            spellContext.delay(delayEvent);
            EventQueue.getServerInstance().addEvent(new RewindEvent(entity, world.getGameTime(), ticksToRewind, spellContext));
            if (rewindable instanceof Player player) {
                Networking.sendToNearbyClient(world, player, new PacketClientRewindEffect(ticksToRewind, player));
            }

            EventQueue.getServerInstance().addEvent(delayEvent);
        }
    }

public static void addFutureServerTask(Level world, Runnable task, boolean forceFuture)
	{
		LogicalSide side = world.isClientSide?LogicalSide.CLIENT: LogicalSide.SERVER;
		//TODO this sometimes causes NPEs?
		BlockableEventLoop<? super TickTask> tmp = LogicalSidedProvider.WORKQUEUE.get(side);
		if(forceFuture)
		{
			int tick;
			if(world.isClientSide)
				tick = 0;
			else
				tick = ((MinecraftServer)tmp).getTickCount();
			tmp.tell(new TickTask(tick, task));
		}
		else
			tmp.submitAsync(task);
	}

@Override
    public void onHackComplete(Level world, BlockPos pos, Player player) {
        if (world instanceof ServerLevel serverLevel) {
            BlockState state = world.getBlockState(pos);

            // set it to inactive initially, so any pending ticks don't just wake it up again
            world.setBlock(pos, state.setValue(PHASE, SculkSensorPhase.INACTIVE), Block.UPDATE_ALL);

            // and once the cooldown duration is passed, set it into cooldown mode for the silencing duration
            serverLevel.getServer().tell(new TickTask(serverLevel.getServer().getTickCount() + SculkSensorBlock.COOLDOWN_TICKS + 1, () -> {
                if (world.getBlockState(pos).getBlock() instanceof SculkSensorBlock) {
                    world.setBlock(pos, state.setValue(PHASE, COOLDOWN).setValue(SculkSensorBlock.POWER, 0), Block.UPDATE_ALL);
                    world.scheduleTick(pos, state.getBlock(), SILENCE_TIME);
                    world.updateNeighborsAt(pos, state.getBlock());
                    world.updateNeighborsAt(pos.below(), state.getBlock());
                }
            }));
        }
    }

public static void playerCloned(ServerPlayer ignoredOldPlayer, ServerPlayer newPlayer, boolean wonGame) {
		if (!wonGame) {
			ServerConfig.limitedLives().ifPresent(maxLives -> FTBTeamsAPI.api().getManager().getTeamForPlayer(newPlayer).ifPresent(team -> {
				if (team instanceof PartyTeam partyTeam) {
					MinecraftServer server = newPlayer.level().getServer();
					// defer a tick so player is alive again and gets client team syncs
                    server.schedule(new TickTask(server.getTickCount(), () -> {
                        int newLives = partyTeam.getProperty(TeamProperties.LIVES_REMAINING) - 1;
                        if (newLives >= 0) {
                            partyTeam.setProperty(TeamProperties.LIVES_REMAINING, newLives);
                            partyTeam.syncOnePropertyToTeam(TeamProperties.LIVES_REMAINING, newLives);
                            partyTeam.sendMessage(Util.NIL_UUID, Component.translatable("ftbteams.lost_a_life", newLives, maxLives).withStyle(ChatFormatting.RED));
                        } else {
                            kickPlayerNoLivesLeft(newPlayer, partyTeam);
                        }
                    }));
				}
			}));
		}
	}

