public static void handle(PacketEntityLaser message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      ServerPlayer sender = (ServerPlayer) ctx.player();
      Level level = sender.level();
      Entity target = level.getEntity(message.entityId);
      //validate also covers delay
      ItemStack stack = LaserItem.getIfHeld(sender);
      if (PacketEntityLaser.canShoot(sender, target, stack)) {
        IEnergyStorage storage = stack.getCapability(Capabilities.EnergyStorage.ITEM);
        if (storage != null) {
          float dmg = message.crosshair ? ConfigRegistry.LaserItemDamageClose.get() : ConfigRegistry.LaserItemDamageFar.get();
          if (target.hurt(level.damageSources().indirectMagic(sender, sender), dmg)) {
            //DRAIN RF ETC 
            LaserItem.resetStackDamageCool(stack, level.getGameTime());
            storage.extractEnergy(ConfigRegistry.LaserItemEnergy.get(), false);
          }
        }
        //        target.causeFallDamage(0, 0, null);
      }
    });

  }

@Override
	public void process(IPayloadContext context)
	{
		context.enqueueWork(() -> {
			Level level = context.player().level();
			IEnergyStorage storage = pos.map(
					bp -> level.getCapability(EnergyStorage.BLOCK, bp, null),
					id -> {
						Entity entity = level.getEntity(id);
						if(entity!=null)
							return entity.getCapability(EnergyStorage.ENTITY, null);
						else
							return null;
					}
			);
			RemoteEnergyData data = null;
			if(storage!=null&&storage.getMaxEnergyStored() > 0)
				data = new RemoteEnergyData(
						pos, level.getGameTime(), true, storage.getEnergyStored(), storage.getMaxEnergyStored()
				);
			if(data==null)
				data = new RemoteEnergyData(pos, level.getGameTime(), false, 0, 0);
			PacketDistributor.sendToPlayer(IMessage.serverPlayer(context), new MessageStoredEnergy(data));
		});
	}

private void checkStateUpdates(ItemStack loadedStack, boolean didWork) {
        BlockState state = getBlockState();
        if (state.getBlock() == ModBlocks.UV_LIGHT_BOX.get()) {
            boolean loaded = state.getValue(UVLightBoxBlock.LOADED);
            boolean updateNeeded = false;
            if (loaded == loadedStack.isEmpty()) {
                state = state.setValue(UVLightBoxBlock.LOADED, !loadedStack.isEmpty());
                updateNeeded = true;
            }
            if (didWork != getBlockState().getValue(UVLightBoxBlock.LIT)) {
                state = state.setValue(UVLightBoxBlock.LIT, didWork);
                updateNeeded = true;
            }
            long now = nonNullLevel().getGameTime();
            if (updateNeeded) {
                if (now - lastStateUpdateTime > 10) {
                    updateBlockStateImmediate(state, now);
                } else {
                    pendingState = state;
                }
            } else if (pendingState != null && now - lastStateUpdateTime > 10) {
                updateBlockStateImmediate(pendingState, now);
            }
        }
    }

public void dropSecondPartContents(ChestBlock chestBlock, BlockPos dropPosition) {
		if (isLinkedStorage()) {
			return;
		}
		InventoryHandler invHandler = getStorageWrapper().getInventoryHandler();

		List<ItemStack> dropItems = new ArrayList<>();

		for (int slot = chestBlock.getNumberOfInventorySlots(); slot < invHandler.getSlots(); slot++) {
			ItemStack slotStack = invHandler.getSlotStack(slot);

			if (!slotStack.isEmpty()) {
				dropItems.add(slotStack.copy());
				invHandler.setStackInSlot(slot, ItemStack.EMPTY);
			}
		}

		if (level instanceof ServerLevel serverLevel) {
			serverLevel.getServer().tell(new TickTask(serverLevel.getServer().getTickCount(), () -> dropItems
					.forEach(itemStack -> Containers.dropItemStack(serverLevel, dropPosition.getX(), dropPosition.getY(), dropPosition.getZ(), itemStack))));
		}

		int inventorySlotDiff = chestBlock.getNumberOfInventorySlots() - invHandler.getSlots();

		changeStorageSize(inventorySlotDiff, 0);
		deleteSettingsFromSlot(this, chestBlock.getNumberOfInventorySlots());
		getStorageWrapper().getSettingsHandler().getTypeCategory(ItemDisplaySettingsCategory.class).setDisplaySide(DisplaySide.FRONT);
		getStorageWrapper().getUpgradeHandler().refreshUpgradeWrappers();
		WorldHelper.notifyBlockUpdate(this);
	}

@Override
    public void tick() {
        super.tick();
        if (this.getWorld().isClient()) {
            setupAnimationStates();
            spawnExistenceParticles();
        } else {
            if (pendingSpawnSound) {
                pendingSpawnSound = false;
                if (behaviour != null) {
                    playConfiguredSound(behaviour.sounds.spawn);
                    emitSpawnFx();
                }
            }
            cooldownManager.tickUpdate();
            if (timeToLive > 0 && this.age >= timeToLive) {
                this.discard();
            } else if (this.age < spawnEndAge) {
                setPhase(PHASE_SPAWNING);
            } else if (timeToLive > 0 && this.age >= despawnStartAge) {
                setPhase(PHASE_DESPAWNING);
            } else {
                setPhase(PHASE_ACTIVE);
            }
            // Tally the owner's hits so MirrorOwnerAttackGoal can apply attack_with_owner_hits.
            tickOwnerAttackTracking();
            // Per-tick clear triggers (after_ticks, out_of_detection_range) from clear_conditions.
            tickClearConditions();
            // Action animations are self-terminating now:
            //   - ATTACK_ANIMATION / SPELL_RELEASE_ANIMATION carry a fixed duration; the
            //     client stops their AnimationState once `age - startAge >= duration`.
            //   - SPELL_CAST_ANIMATION is ended explicitly by SpellCastGoal via
            //     onSpellCastEnded() on release or cancellation.
        }
    }

