@SubscribeEvent
	public void onServerWorldTick(TickEvent.LevelTickEvent event)
	{
		if (event.level.isClientSide)
			return;

		ResourceLocation rl = WorldDemonWillHandler.getDimensionResourceLocation(event.level);
//        int dim = event.world.provider.getDimension();
		if (event.phase == TickEvent.Phase.END)
		{
			if (!SERVER_TICKS.containsKey(rl))
				SERVER_TICKS.put(rl, 0);

			int ticks = (SERVER_TICKS.get(rl));

			if (ticks % 20 == 0)
			{
//				CopyOnWriteArrayList<PosXY> dirtyChunks = WorldDemonWillHandler.dirtyChunks.get(rl);
				ConcurrentLinkedQueue<PosXY> dirtyChunks = WorldDemonWillHandler.dirtyChunks.get(rl);
				if ((dirtyChunks != null) && (dirtyChunks.size() > 0))
				{
					for (PosXY pos : dirtyChunks)
					{
						ChunkAccess chunk = event.level.getChunk(pos.x, pos.y, ChunkStatus.FULL, false);
						if (chunk != null)
						{
							chunk.setUnsaved(true);
						}
					}

					dirtyChunks.clear();
				}
			}

			SERVER_TICKS.put(rl, ticks + 1);
		}

	}

public void tick() {
        if (!this.pendingChalices.isEmpty()) {
            this.pendingChalices.forEach(this::registerChalice);
            this.pendingChalices.clear();
        }
        switch (dimensionState) {
            case INVALID -> {
                LOGGER.error("The velmorra dimension is invalid, the level will be destroyed");
                destroyDimension();
            }
            case DEAD -> {
                deathTicks++;
                if (deathTicks >= COLLAPSE_DURATION) {
                    destroyDimension();
                    return;
                }
                while (warningsSend < COLLAPSE_WARNINGS.length && deathTicks >= COLLAPSE_WARNINGS[warningsSend].tick()) {
                    sendMessage(Component.translatable(COLLAPSE_WARNINGS[warningsSend].translationKey()));
                    warningsSend++;
                }
                int remaining = COLLAPSE_DURATION - deathTicks;
                if (remaining <= 10 * 20 && remaining % 20 == 0) {
                    sendOverlayMessage(Component.translatable("message.vampirism.velmorra.collapse.countdown", remaining / 20));
                }
                // regular sync covers late joiners as well
                if (deathTicks % 20 == 1) {
                    var packet = new ClientboundVelmorraCollapsePacket(deathTicks / (float) COLLAPSE_DURATION);
                    this.level.players().forEach(player -> player.connection.send(packet));
                }
            }
            case NONE -> {
                if (chaliceReferences.values().stream().filter(r -> r.active).count() >= 4) {
                    startFight();
                    return;
                }
            }
            case FIGHTING -> {
                if (level.getGameTime() % 100 == 0){
                    level.players().forEach(event::addPlayer);
                    if (this.draculaId == null) {
                        LOGGER.error("Dracula id is null");
                        this.dimensionState = State.INVALID;
                    } else if (this.dracula == null || this.dracula.get() == null) {
                        Entity entity = this.level.getEntity(this.draculaId);
                        if (entity instanceof Dracula dra) {
                            this.dracula = new WeakReference<>(dra);
                        } else {
                            LOGGER.error("Dracula is null");
                            this.dimensionState = State.INVALID;
                        }
                    }
                }
            }
        }
    }

@Override
    public void tick(BlockEntity ownerTE) {
        Level world = Objects.requireNonNull(ownerTE.getLevel());
        Direction actualLeakDir = leakDir;

        if (!world.isClientSide) {
            if (pendingAir != 0) {
                // add any saved air if this is being restored from item stack component data
                // need to wait till now to ensure saved volume upgrades are also accounted for
                addAir(pendingAir);
                pendingAir = 0;
                if (getPressure() > getDangerPressure()) {
                    // shouldn't happen but just in case
                    setPressure(getDangerPressure() - 0.1f);
                }
            }

            // server
            disperseAir(ownerTE);

            BlockPos pos = ownerTE.getBlockPos();
            if (safetyLeakDir != null) {
                float pressure = getPressure();
                if (!safetyLeaking && safetyPredicate.test(pressure)) {
                    safetyLeaking = true;
                } else if (safetyLeaking && !safetyPredicate.test(pressure + 0.2f)) {
                    safetyLeaking = false;
                }
                // also cap pressure at critical level (it's still possible for air to added faster than it can vent)
                if (pressure >= getCriticalPressure()) {
                    int wanted = (int)(getCriticalPressure() * getVolume());
                    addAir(wanted - getAir());
                }
            } else if (Objects.requireNonNull(world.getServer()).getTickCount() > 20) {
                // little kludge: no overpressure checks right after server starts up (just to be safe)
                doOverpressureChecks(ownerTE, world, pos);
            }

            actualLeakDir = safetyLeaking ? safetyLeakDir : leakDir;
            if (prevLeakDir != actualLeakDir || actualLeakDir != null && (world.getGameTime() & 0x1f) == 0) {
                // if leak status changes, sync pressure & leak dir to the client
                // OR if already leaking, periodically sync pressure & leak dir to the client
                NetworkHandler.sendToAllTracking(PacketUpdatePressureBlock.create(ownerTE.getBlockPos(),
                        anyConnectableFace(), actualLeakDir, getAir()
                ), ownerTE);
            }

            prevAir = getAir();
            prevLeakDir = actualLeakDir;
        }

        if (actualLeakDir != null && getAir() != 0) {
            handleAirLeak(ownerTE, actualLeakDir);
        }
    }

@Override
	public void tick() {
		super.tick();

		boolean doLogic = !level.isClientSide || isVirtual();
		State prevState = state;
		float totalTime = Math.max(3, (float) launcher.getTotalFlyingTicks());

		if (scanCooldown > 0)
			scanCooldown--;

		if (launch) {
			launch = false;
			activateDeferred();
		}

		for (Iterator<IntAttached<ItemStack>> iterator = launchedItems.iterator(); iterator.hasNext();) {
			IntAttached<ItemStack> intAttached = iterator.next();
			boolean hit = false;
			if (intAttached.getSecond() == trackedItem)
				hit = scanTrajectoryForObstacles(intAttached.getFirst());
			float maxTime = earlyTarget != null ? Math.min(earlyTargetTime, totalTime) : totalTime;
			if (hit || intAttached.exceeds((int) maxTime)) {
				placeItemAtTarget(doLogic, maxTime, intAttached);
				iterator.remove();
			}
			intAttached.increment();
		}

		if (state == State.LAUNCHING) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			lidProgress.tickChaser();
			if (lidProgress.getValue() > 1 - 1 / 16f && doLogic) {
				state = State.RETRACTING;
				lidProgress.setValue(1);
			}
		}

		if (state == State.CHARGED) {
			lidProgress.setValue(0);
			lidProgress.updateChaseSpeed(0);
			if (doLogic)
				ejectIfTriggered();
		}

		if (state == State.RETRACTING) {
			if (lidProgress.getChaseTarget() == 1 && !lidProgress.settled()) {
				lidProgress.tickChaser();
			} else {
				lidProgress.updateChaseTarget(0);
				lidProgress.updateChaseSpeed(0);
				if (lidProgress.getValue() == 0 && doLogic) {
					state = State.CHARGED;
					lidProgress.setValue(0);
					sendData();
				}

				float value = Mth.clamp(lidProgress.getValue() - getWindUpSpeed(), 0, 1);
				lidProgress.setValue(value);

				int soundRate = (int) (1 / (getWindUpSpeed() * 5)) + 1;
				float volume = .125f;
				float pitch = 1.5f - lidProgress.getValue();
				if (((int) level.getGameTime()) % soundRate == 0 && doLogic)
					level.playSound(null, worldPosition, SoundEvents.WOODEN_BUTTON_CLICK_OFF, SoundSource.BLOCKS,
						volume, pitch);
			}
		}

		if (state != prevState)
			notifyUpdate();
	}

protected void tickDeath() {
        ++this.deathTime;
        if (this.deathTime == 1){
            if (this.pendingTeleportSearch != null) {
                this.pendingTeleportSearch.cancel(true);
                this.pendingTeleportSearch = null;
            }
            this.antiRegen = 0;
            this.antiRegenTotal = 0;
            this.toTeleportTime = 0;
            this.toTeleportPos = null;
            this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
        }
        if (MobsConfig.FancierApostleDeath.get() || (this.isInNether() && MobsConfig.ApostleNetherFancyDeath.get())) {
            this.setNoGravity(true);
            if (this.getKillCredit() instanceof Player){
                this.lastHurtByPlayerTime = 100;
            } else {
                this.lastHurtByMobTimestamp = 100;
            }
            if (this.deathTime < 180) {
                if (this.deathTime > 20) {
                    this.move(MoverType.SELF, new Vec3(0.0D, 0.1D, 0.0D));
                }
                ExplosionUtil.lootExplode(this.level, this, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0.0F, false, Explosion.BlockInteraction.KEEP, LootingExplosion.Mode.LOOT);
            } else if (this.deathTime != 200) {
                this.move(MoverType.SELF, new Vec3(0.0D, 0.0D, 0.0D));
            }
            if (this.deathTime >= 200) {
                this.move(MoverType.SELF, new Vec3(0.0D, -4.0D, 0.0D));
                if (this.onGround() || this.getY() <= this.level.getMinBuildHeight()) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        if (serverLevel.getLevelData().isThundering()) {
                            serverLevel.setWeatherParameters(6000, 0, false, false);
                        }
                        for (int k = 0; k < 200; ++k) {
                            float f2 = random.nextFloat() * 4.0F;
                            float f1 = random.nextFloat() * ((float) Math.PI * 2F);
                            double d1 = Mth.cos(f1) * f2;
                            double d2 = 0.01D + random.nextDouble() * 0.5D;
                            double d3 = Mth.sin(f1) * f2;
                            serverLevel.sendParticles(ParticleTypes.LARGE_SMOKE, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                            serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                        }
                        serverLevel.sendParticles(ParticleTypes.EXPLOSION_EMITTER, this.getX(), this.getY(), this.getZ(), 0, 1.0F, 0.0F, 0.0F, 0.5F);
                    }
                    this.playSound(SoundEvents.GENERIC_EXPLODE, 4.0F, (1.0F + (this.level.random.nextFloat() - this.level.random.nextFloat()) * 0.2F) * 0.7F);
                    this.playSound(this.getTrueDeathSound(), 5.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
                    this.die(this.deathBlow);
                    this.remove(RemovalReason.KILLED);
                }
            }
        } else {
            this.move(MoverType.SELF, new Vec3(0.0D, 0.0D, 0.0D));
            if (this.deathTime == 1){
                if (!this.level.isClientSide) {
                    ServerLevel ServerLevel = (ServerLevel) this.level;
                    if (ServerLevel.getLevelData().isThundering()) {
                        ServerLevel.setWeatherParameters(6000, 0, false, false);
                    }
                    for (int k = 0; k < 200; ++k) {
                        float f2 = random.nextFloat() * 4.0F;
                        float f1 = random.nextFloat() * ((float) Math.PI * 2F);
                        double d1 = Mth.cos(f1) * f2;
                        double d2 = 0.01D + random.nextDouble() * 0.5D;
                        double d3 = Mth.sin(f1) * f2;
                        ServerLevel.sendParticles(ParticleTypes.LARGE_SMOKE, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                        ServerLevel.sendParticles(ParticleTypes.FLAME, this.getX() + d1 * 0.1D, this.getY() + 0.3D, this.getZ() + d3 * 0.1D, 0, d1, d2, d3, 0.5F);
                    }
                    for (int l = 0; l < 16; ++l){
                        ServerLevel.sendParticles(ParticleTypes.FLAME, this.getRandomX(1.0F), this.getRandomY() - 0.25F, this.getRandomZ(1.0F), 1, 0, 0, 0, 0);
                    }
                }
                this.die(this.deathBlow);
                this.playSound(this.getTrueDeathSound(), 5.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            }
            if (this.deathTime >= 30) {
                this.remove(RemovalReason.KILLED);
            }
        }

    }

