@SubscribeEvent
	public static void vanishTicker(TickEvent.WorldTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		if (event.type != TickEvent.Type.WORLD) return;
		if (event.side != Side.SERVER) return;

		final int sizeAddsBefore = adds.size();
		final int sizeVanishesBefore = vanishes.size();

		for (VanishedObject entry; ((entry = adds.pollFirst()) != null); ) {
			vanishes.add(entry);
		}
		vanishes.removeIf(entry -> {
			if (--entry.tick < 0) {
				Entity e = event.world.getEntityByID(entry.entityID);
				if (e != null && !event.world.isRemote) {
					event.world.playSound(null, e.getPosition(), ModSounds.ETHEREAL_PASS_BY, SoundCategory.NEUTRAL, 0.5f, 1);
				}

				return true;
			}
			return false;
		});

		final int sizeAddsAfter = adds.size();
		final int sizeVanishesAfter = vanishes.size();

		if (!event.world.isRemote && sizeAddsAfter != sizeAddsBefore || sizeVanishesAfter != sizeVanishesBefore) {
			PacketHandler.NETWORK.sendToAll(new PacketSyncVanish(serialize()));
		}
	}

@SubscribeEvent
	public static void onPlayerTickEvent(TickEvent.PlayerTickEvent event){

		if(event.phase == TickEvent.Phase.START){

			EntityLiving possessee = getPossessee(event.player);

			if(possessee != null){
				// Updating these to the player's variables won't have an effect on player movement, but it will
				// affect various bits of mob-specific logic
				possessee.setPosition(event.player.posX, event.player.posY, event.player.posZ);
				possessee.motionX = event.player.motionX;
				possessee.motionY = event.player.motionY;
				possessee.motionZ = event.player.motionZ;
				possessee.onGround = event.player.onGround;

				possessee.onUpdate(); // Event though it's not in the world, it still needs updating
				possessee.ticksExisted++; // Normally gets updated from World

				if(possessee.getHealth() <= 0){
					((Possession)Spells.possession).endPossession(event.player);
				}

				performAbilities(possessee, event.player);
			}
		}

		// Right at the end of EntityPlayer#onUpdate() it calls EntityPlayer#updateSize(), which resets the player's
		// size (and is also where this event is fired from, oddly enough) ... but not on my watch!
		if(event.phase == TickEvent.Phase.END){
			EntityLiving possessee = getPossessee(event.player);
			if(possessee != null){
				setSize(event.player, possessee.width, possessee.height);
			}
		}
	}

@SubscribeEvent
    public static synchronized void runScheduledTasks(TickEvent event)
    {
        if ((event instanceof TickEvent.ServerTickEvent || event instanceof TickEvent.ClientTickEvent) && event.phase == TickEvent.Phase.START)
        {
            List<QueueEntry> schedule = event.side.isClient() ? CLIENT_SCHEDULE : SERVER_SCHEDULE;

            // Iterate through all active tasks
            if (!schedule.isEmpty())
            {
                for (int i = 0; i < schedule.size(); i++)
                {
                    QueueEntry entry = schedule.get(i);
                    int ticks = entry.time;

                    // If the task is ready to run, run it and remove it from the schedule
                    if (ticks <= 0)
                    {
                        try
                        {   entry.task.run();
                        }
                        catch (Exception e)
                        {   ColdSweat.LOGGER.error("Error while running scheduled task", e);
                            throw e;
                        }
                        schedule.remove(i);
                        i--;
                    }
                    // Otherwise, decrement the task's tick count
                    else
                    {   entry.time = ticks - 1;
                    }
                }
            }
        }
    }

@SubscribeEvent
	public void playerTickPost(TickEvent.PlayerTickEvent event) {
		// this is only relevant for the local player
		if (event.phase == TickEvent.Phase.END && event.player == entityLiving && !event.player.isElytraFlying()) {
			// bounce up. This is to pcircumvent the logic that resets y motion after landing
			if (event.player.ticksExisted == bounceTick) {
				event.player.motionY = bounce;
				bounceTick = 0;
			}

			// preserve motion
			if (!entityLiving.onGround && entityLiving.ticksExisted != bounceTick) {
				if (lastMovX != entityLiving.motionX || lastMovZ != entityLiving.motionZ) {
					double f = 0.91d + 0.025d;
					entityLiving.motionX /= f;
					entityLiving.motionZ /= f;
					entityLiving.isAirBorne = true;
					lastMovX = entityLiving.motionX;
					lastMovZ = entityLiving.motionZ;
				}
			}

			// timing the effect out
			if (wasInAir && entityLiving.onGround) {
				if (timer == 0) {
					timer = entityLiving.ticksExisted;
				} else if (entityLiving.ticksExisted - timer > 5) {
					MinecraftForge.EVENT_BUS.unregister(this);
					bouncingEntities.remove(entityLiving);
				}
			} else {
				timer = 0;
				wasInAir = true;
			}
		}
	}

