public synchronized void run(Runnable runnable) {
		if (future != null) {
			future.cancel(false);
		}
		future = executor.schedule(runnable, delay);
	}

public boolean tick() {
            if (cancelled)
                return true;

            if (ticks == 0)
                task.run();

            return --ticks < 0;
        }

public static void tick() {
		for(SpellContext context : new ArrayList<>(CONTEXTS)) {
			context.delay--;
			if(context.delay <= 0) {
				CONTEXTS.remove(context);
				context.delay = 0;
				context.cspell.safeExecute(context);
			}
		}
	}

default void schedule(int ticks, Runnable task) {
        if (ticks < 0) {
            task.run();
            return;
        }
        if (ticks == 0) {
            getImmediateTasks().add(task);
            return;
        }
        long executionTime = getSchedulerTime() + ticks;
        var list = getScheduledTasks().getOrDefault(executionTime, new ArrayList<>());
        list.add(task);
        getScheduledTasks().put(executionTime, list);
    }

private static void execute(List<RunnableEntry> tasks) {
        if (tasks == null || tasks.isEmpty()) return;
        var iter = tasks.iterator();
        while (iter.hasNext()) {
            var task = iter.next();
            if (task.delay <= 0) {
                try {
                    task.runnable.run();
                } catch (Exception e) {
                    GTCEu.LOGGER.error("error while schedule gregtech task", e);
                }
                iter.remove();
            } else {
                task.delay--;
            }
        }
    }

