        }
    }

public void tick(@Nullable ServerTickEvent.Post e) {
        if (events.isEmpty()) {
            return;
        }

        List<ITimedEvent> stale = new ObjectArrayList<>();
        // Enhanced-for or iterator will cause a concurrent modification on integrated servers.
        for (int i = 0; i < events.size(); i++) {
            ITimedEvent event = events.get(i);
            if (event.isExpired()) {
                stale.add(event);
            } else {
                if (e == null)
                    event.tick(false);
                else
                    event.tick(e);
            }
        }
        this.events.removeAll(stale);
    }

public static void addManaEvent(Level world, Class<? extends SourcelinkTile> tileType, int amount, Event event, BlockPos sourcePos) {
        List<BlockPos> stalePos = new ArrayList<>();
        Set<BlockPos> worldList = posMap.getOrDefault(world.dimension().location().toString(), new HashSet<>());
        for (BlockPos p : worldList) {
            if (!world.isLoaded(p))
                continue;
            BlockEntity entity = world.getBlockEntity(p);
            if (world.getBlockEntity(p) == null || !(entity instanceof SourcelinkTile sourcelinkTile)) {
                stalePos.add(p);
                continue;
            }
            if (entity.getClass().equals(tileType) && sourcelinkTile.eventInRange(sourcePos, event) && sourcelinkTile.canAcceptSource()) {
                sourcelinkTile.getManaEvent(sourcePos, amount);
                break;
            }
        }
        for (BlockPos p : stalePos) {
            worldList.remove(p);
        }
    }

public static @Nullable <T extends RangeRitual> T getRitual(Level level, Class<T> type, Predicate<T> isMatch) {
        Set<BlockPos> worldList = posMap.getOrDefault(level.dimension().location().toString(), new HashSet<>());
        List<BlockPos> stalePos = new ArrayList<>();
        for (BlockPos p : worldList) {
            if (!level.isLoaded(p))
                continue;
            BlockEntity entity = level.getBlockEntity(p);
            if (!(entity instanceof RitualBrazierTile brazierTile)) {
                stalePos.add(p);
                continue;
            }
            AbstractRitual ritual = brazierTile.ritual;
            if (ritual != null && ritual.getClass().equals(type) && isMatch.test((T) ritual)) {
                return (T) ritual;
            }
        }
        for (BlockPos p : stalePos) {
            worldList.remove(p);
        }
        return null;
    }

