public final void onLevelReady() {
        // If load() hasn't been called yet, don't
        if (!hasLoaded) {
            return;
        }

        // Load any pending tasks.
        if (pendingTask != null) {
            currentTask = loadTask(getLevel().registryAccess(), pendingTask);
