                    } else if (packet.mode == 1){
                        trampler.setDashing(true);
                    } else if (packet.mode == 2){
                        trampler.setDashing(false);
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

private <BE extends @Nullable BlockEntity> TransitResponse insertUnchecked(Level level, BE outputter, TransitRequest request, TransporterStack stack, int min,
          @Nullable TransactionContext transaction, PathCalculator<BE> pathCalculator) {
        //TODO: Technically if we still have more of the same item input, we want to allow trying to insert it into different transport
        // destinations, which this doesn't do as it only checks once, rather than trying to check all destinations we can send to
        // if the amount would be split between multiple destinations
        TransitResponse response = pathCalculator.calculate(stack, level, request, outputter, this, min, transaction);
        if (!response.isEmpty()) {
            stack.setStack(response.itemType(), response.sendingAmount());
            if (transaction == null) {
                //If there is no current transaction context, just directly emit the stack
                emitStack(stack);
            } else {
                //Otherwise, queue it to emit when the transaction chain finishes
                RootCommitJournal onRootCommit = new RootCommitJournal(() -> emitStack(stack));
                onRootCommit.updateSnapshots(transaction);
            }
        }
        return response;
    }

public int getTotalPromisedAndRemoveExpired(ItemStack stack, int expiryTime) {
		int promised = 0;
		List<RequestPromise> list = promisesByItem.get(stack.getItem());
		if (list == null)
			return promised;

		for (Iterator<RequestPromise> iterator = list.iterator(); iterator.hasNext();) {
			RequestPromise promise = iterator.next();
			if (!ItemStack.isSameItemSameComponents(promise.promisedStack.stack, stack))
				continue;
			if (expiryTime != -1 && promise.ticksExisted >= expiryTime) {
				iterator.remove();
				onChanged.run();
				continue;
			}

			promised += promise.promisedStack.count;
		}
		return promised;
	}

private boolean tryUseOn(ServerPlayer player, ItemStack stack) {
        return readBlockPos(stack).map(gPos -> {
            Level level = player.getServer().getLevel(gPos.dimension());
            if (level != player.level() || !player.level().isLoaded(gPos.pos())) {
                player.displayClientMessage(Component.translatable("ftbquests.message.task_screen_inaccessible").withStyle(ChatFormatting.RED), true);
                return false;
            }
            if (level.getBlockEntity(gPos.pos()) instanceof ITaskScreen taskScreen) {
                if (TaskScreenBlock.hasPermissionToEdit(player, taskScreen)) {
                    taskScreen.getCoreScreen().ifPresent(coreScreen -> new TaskScreenConfigRequest(coreScreen.getBlockPos()).sendTo(player));
                    return true;
                } else {
                    player.displayClientMessage(Component.translatable("block.ftbquests.screen.no_permission").withStyle(ChatFormatting.RED), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("ftbquests.message.missing_task_screen").withStyle(ChatFormatting.RED), true);
            }
            return false;
        }).orElse(false);
    }

