@Override
	public void process(IPayloadContext context)
	{
		context.enqueueWork(() -> {
			Level world = ImmersiveEngineering.proxy.getClientWorld();
			if(world!=null) // This can happen if the task is scheduled right before leaving the world
			{
				if(this.remove)
					ModelPowerpack.PLAYER_ATTACHED_TO.remove(this.player);
				else
				{
					GlobalWireNetwork global = GlobalWireNetwork.getNetwork(world);
					global.getLocalNet(this.from).getConnections(this.from).stream().filter(conn ->
							// filter to connections matching both points
							(conn.getEndA().position().equals(this.from)&&conn.getEndB().position().equals(this.to))
									||(conn.getEndB().position().equals(this.from)&&conn.getEndA().position().equals(this.to))
					).findFirst().ifPresent(
							// add to map
							c -> ModelPowerpack.PLAYER_ATTACHED_TO.put(this.player, c)
					);
				}
			}
		});
	}

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            for (var stack : Arrays.asList(player.getMainHandItem(), player.getOffhandItem())) {
                if (!(stack.getItem() instanceof CutGlassBootItem item))
                    continue;

                var entries = item.getFluidEntries(player, stack);

                if (entries.isEmpty())
                    continue;

                item.setSelectedFluidIndex(player, stack, Math.floorMod(item.getSelectedFluidIndex(player, stack) + this.getDelta(), entries.size()));

                var fluid = BuiltInRegistries.FLUID.get(ResourceLocation.parse(item.getSelectedFluid(player, stack).toString()));

                if (fluid == Fluids.EMPTY)
                    continue;

                player.displayClientMessage(Component.literal(fluid.getFluidType().getDescription().getString()), true);
            }
        });
    }

@Override
    public InteractionResult useOn(UseOnContext ctx) {
        ItemStack stack = ctx.getPlayer().getItemInHand(ctx.getHand());

        INetwork network = NetworkUtils.getNetworkFromNode(NetworkUtils.getNodeFromBlockEntity(ctx.getLevel().getBlockEntity(ctx.getClickedPos())));
        if (network != null) {
            CompoundTag tag = stack.getTag();

            if (tag == null) {
                tag = new CompoundTag();
            }

            tag.putInt(NBT_NODE_X, network.getPosition().getX());
            tag.putInt(NBT_NODE_Y, network.getPosition().getY());
            tag.putInt(NBT_NODE_Z, network.getPosition().getZ());
            tag.putString(NBT_DIMENSION, ctx.getLevel().dimension().location().toString());

            stack.setTag(tag);

            return InteractionResult.SUCCESS;
        }

        return InteractionResult.PASS;
    }

