                            } else {
                                if (message.baby) {
                                    dragon.stopRiding();
                                } else {
                                    player.stopRiding();
                                }
                            }
                        }
                    }
                }
            }
        }

@Override
	public void process(IPayloadContext context)
	{
		context.enqueueWork(() -> {
			ConnectionPoint start = this.connection.start();
			ConnectionPoint end = this.connection.end();
			WireType type = this.connection.type();
			WireLogger.logger.debug(
					"Processing sync for connection from {} to {}, type {}, op {}",
					start, end, type, operation.name()
			);
			Player player = ImmersiveEngineering.proxy.getClientPlayer();
			Level w = player.level();

			GlobalWireNetwork globalNet = GlobalWireNetwork.getNetwork(w);
			Connection connection = this.connection.toConnection();
			if(operation!=ADD&&globalNet.getNullableLocalNet(start)!=null&&globalNet.getNullableLocalNet(end)!=null)
			{
				globalNet.removeConnection(connection);
				removeProxyIfNoWires(start, globalNet);
				removeProxyIfNoWires(end, globalNet);
			}
			if(operation!=REMOVE)
				globalNet.addConnection(connection);
			Set<SectionPos> sectionsToRerender = new ObjectArraySet<>();
			WireUtils.forEachRenderPoint(connection, ($, $2, section) -> sectionsToRerender.add(section));
			for(SectionPos section : sectionsToRerender)
				Minecraft.getInstance().levelRenderer.setSectionDirty(section.x(), section.y(), section.z());
		});
	}

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();
            var level = player.level();

            CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(this.getIdentifier(), this.getIndex())).ifPresent(slot -> {
                var stack = slot.stack();
                var relic = (RollerSkateItem) stack.getItem();

                var spark = new RollerSparkEntity(RelicsEntities.ROLLER_SPARK.get(), level);

                spark.setDeltaMovement(this.motion.x(), this.motion.y(), this.motion.z());
                spark.setPos(this.pos.x(), this.pos.y(), this.pos.z());
                spark.setFlawless(this.flawless);
                spark.setDamage(this.damage);
                spark.setIgnite(this.ignite);
                spark.setStack(stack);

                if (level instanceof ServerLevel serverLevel)
                    spark.setOwner(serverLevel.getEntity(UUID.fromString(this.owner)));

                level.addFreshEntity(spark);

                relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("sparks_created").addValue(1);

                if (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("sparks_created").getValue() % 10 == 0)
                    relic.getRelicData(player, stack).getLevelingData().addExperience("skating", "creating_sparks", 1);
            });
        });
