public static void handle(MessageHurtMultipart message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            context.get().enqueueWork(() -> {
                Player player = context.get().getSender();
                if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                    player = AlexsMobs.PROXY.getClientSidePlayer();
                }

                if (player != null) {
                    if (player.level() != null) {
                        Entity part = player.level().getEntity(message.part);
                        Entity parent = player.level().getEntity(message.parent);
                        Registry<DamageType> registry = player.level().registryAccess().registry(Registries.DAMAGE_TYPE).get();
                        DamageType dmg = registry.get(new ResourceLocation(message.damageType));
                        if (dmg != null) {
                            Holder<DamageType> holder = registry.getHolder(registry.getId(dmg)).orElseGet(null);
                            if (holder != null) {
                                DamageSource source = new DamageSource(registry.getHolder(registry.getId(dmg)).get());
                                if (part instanceof IHurtableMultipart && parent instanceof LivingEntity) {
                                    ((IHurtableMultipart) part).onAttackedFromServer((LivingEntity) parent, message.damage, source);
                                }
                                if (part == null && parent != null && parent.isMultipartEntity()) {
                                    parent.hurt(source, message.damage);
                                }

                            }
                        }

                    }
                }
            });
        }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();
            var level = player.level();
            var random = level.getRandom();
            var entity = level.getEntity(this.getId());

            if (entity == null)
                return;

            var motion = new Vec3(this.getMotion());
            var speed = Math.abs(motion.y());

            entity.setDeltaMovement(motion);

            for (float i = 0; i < speed * 5F; i += 0.1F) {
                var angle = random.nextFloat() * Math.PI * 2;
                var radius = Math.sqrt(random.nextFloat()) * speed * 0.15F;

                var dx = Math.cos(angle) * radius;
                var dz = Math.sin(angle) * radius;

                level.addParticle(ParticleTypes.CLOUD, entity.getX(), entity.getY(), entity.getZ(), dx, random.nextFloat() * 0.15F, dz);
            }

            for (int i = 0; i < 50 * speed; i += 1) {
                var particleMotion = motion.normalize().scale(random.nextFloat());

                level.addParticle(ParticleTypes.CLOUD, entity.getX() + MathUtils.randomFloat(random) * 0.5F, entity.getY(), entity.getZ() + MathUtils.randomFloat(random) * 0.5F, particleMotion.x(), particleMotion.y(), particleMotion.z());
            }
        });
    }

public void registerAllPackets() {
		if (packetsRegistered)
			throw new IllegalStateException("Cannot call registerAllPackets() more than once!");

		ModContainer container = ModList.get().getModContainerById(modId).orElseThrow();
		container.getEventBus().addListener((RegisterPayloadHandlersEvent e) -> {
			PayloadRegistrar registrar = e.registrar(networkVersion);

			for (CatnipPacketRegistry.PacketType<?> type : packetsView) {
				boolean clientbound = ClientboundPacketPayload.class.isAssignableFrom(type.clazz());
				boolean serverbound = ServerboundPacketPayload.class.isAssignableFrom(type.clazz());
				if (clientbound && serverbound) {
					throw new IllegalStateException("Packet class is both clientbound and serverbound: " + type.clazz());
				} else if (clientbound) {
					CatnipPacketRegistry.PacketType<ClientboundPacketPayload> casted = (CatnipPacketRegistry.PacketType<ClientboundPacketPayload>) type;
					registrar.playToClient(casted.type(), casted.codec(), (payload, ctx) -> {
						ctx.enqueueWork(() -> {
							payload.handleInternal(ctx.player());
						});
					});
				} else if (serverbound) {
					CatnipPacketRegistry.PacketType<ServerboundPacketPayload> casted = (CatnipPacketRegistry.PacketType<ServerboundPacketPayload>) type;
					registrar.playToServer(casted.type(), casted.codec(), (payload, ctx) -> {
						ctx.enqueueWork(() -> {
							payload.handle((ServerPlayer) ctx.player());
						});
					});
				}
			}
		});
		packetsRegistered = true;
	}

@Override
	public void process(IPayloadContext context)
	{
		Player player = context.player();
		context.enqueueWork(() -> {
			ItemStack held = player.getItemInHand(InteractionHand.OFF_HAND);
			if(fetchSlot >= 0)
			{
				ItemStack s = player.getInventory().items.get(fetchSlot);
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(s);
				if(s.getItem() instanceof IEShieldItem&&upgrades.has(UpgradeEffect.MAGNET))
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, new PrevSlot(fetchSlot));
					s.set(IEDataComponents.UPGRADE_DATA, withSlot);
					player.getInventory().items.set(fetchSlot, held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
			else
			{
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(held);
				var prevSlot = upgrades.get(UpgradeEffect.MAGNET).prevSlot();
				if(held.getItem() instanceof IEShieldItem&&((IEShieldItem)held.getItem()).getUpgrades(held).has(UpgradeEffect.MAGNET)&&prevSlot.isPresent())
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, PrevSlot.NONE);
					held.set(IEDataComponents.UPGRADE_DATA, withSlot);
					ItemStack s = player.getInventory().items.get(prevSlot.get());
					player.getInventory().items.set(prevSlot.get(), held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
		});
	}

