public static void consume(SStaffParticlePacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            if (ctx.get().getDirection() == NetworkDirection.PLAY_TO_CLIENT) {
                Level level = Goety.PROXY.getLevel();
                if (level instanceof ClientLevel clientWorld && clientWorld.getEntity(packet.playerId) instanceof Player player) {
                    Optional<Vec3> staffEndPos;
                    if (player == Minecraft.getInstance().player && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON) {
                        // first-person staff end position
                        int arm = (player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1) * (packet.offHand ? -1 : 1);
                        double fovFactor = 960.0 / (double) Minecraft.getInstance().options.fov().get();
                        float horizontalFactor = 0.125F * packet.staffHeight + 0.35F, verticalFactor = 1.5F * packet.staffHeight - 0.45F;
                        Vec3 vec3 = Minecraft.getInstance().gameRenderer.getMainCamera().getNearPlane().getPointOnPlane(horizontalFactor * arm, verticalFactor).scale(fovFactor);
                        staffEndPos = Optional.of(player.getEyePosition().add(vec3));
                    } else {
                        // third person staff end position
                        staffEndPos = ModelUtil.getThirdPersonPlayerHandPosition(
                                player,
                                Minecraft.getInstance().getEntityRenderDispatcher(),
                                player.yBodyRotO,
                                0,
                                packet.offHand ? player.getMainArm().getOpposite() : player.getMainArm(),
                                new Vec3(0, 0.55, -packet.staffHeight)
                        );
                    }
                    if (staffEndPos.isPresent()) {
                        Vec3 pos = staffEndPos.get().add(new Vec3(level.random.nextDouble() - 0.5, level.random.nextDouble() - 0.5, level.random.nextDouble() - 0.5).normalize().scale(packet.range));
                        level.addParticle(
                                new GatherTrailParticleOption(new ColorUtil(packet.color), staffEndPos.get()),
                                pos.x, pos.y, pos.z,
                                0, 0, 0
                        );
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

@Override
	protected void tick(ServerWorld level, E owner, long gameTime) {
		if (owner.isBlocking()) {
			blockTime++;

			LivingEntity target = owner.getLastHurtByMob();

			if (blockTime >= 5) {
				if (BrainUtil.isWithinMeleeAttackRange(owner, target)) {
					owner.swing(Hand.MAIN_HAND);
					owner.doHurtTarget(target);
					doStop(level, owner, gameTime);
				}
				else if (owner.isOnGround()) {
					Vector3d lungeVector = new Vector3d(target.getX() - owner.getX(), 0, target.getZ() - owner.getZ());

					if (lungeVector.lengthSqr() > 1.0E-7D)
						lungeVector = lungeVector.normalize().scale(0.4d);

					owner.setDeltaMovement(lungeVector.x(), 0.1f, lungeVector.z());
				}
			}

			return;
		}

		if (lastHitTime != owner.getLastHurtByMobTimestamp()) {
			lastHitTime = owner.getLastHurtByMobTimestamp();
			stunCount++;
		}

		if (stunCount > 2) {
			if (!(owner.getItemInHand(Hand.OFF_HAND).getItem() instanceof ShieldItem))
				owner.setItemInHand(Hand.OFF_HAND, new ItemStack(Items.SHIELD));

			owner.startUsingItem(Hand.OFF_HAND);
		}
	}

public void handleTransferItems(ServerboundTransferItemsPacket packet, IPayloadContext context) {
            context.enqueueWork(() -> {
                AbstractContainerMenu menu = context.player().containerMenu;
                for (int i = packet.endslot(); i < menu.slots.size(); i++) {
                    for (int j = packet.startslot(); j < packet.endslot(); j++) {
                        int relative = j - packet.startslot();
                        Slot recipeSlot = menu.getSlot(j);
                        Slot invSlot = menu.getSlot(i);

                        if (recipeSlot.getItem().isEmpty()) {
                            continue;
                        }

                        if ((recipeSlot.getItem().isEmpty() && packet.stacks().get(relative).test(invSlot.getItem()))
                                || ItemStack.isSameItemSameComponents(invSlot.getItem(), recipeSlot.getItem())) {
                            if (packet.maxTransfer()) {
                                int toTransfer = invSlot.getItem().getMaxStackSize() - recipeSlot.getItem().getCount();
                                int actual = Math.min(invSlot.getItem().getCount(), toTransfer);

                                if (actual == 0) {
                                    break;
                                }

                                recipeSlot.set(invSlot.getItem().copyWithCount(actual +  recipeSlot.getItem().getCount()));
                                invSlot.getItem().shrink(actual);

                                if (actual == toTransfer) {
                                    break;
                                }
                            } else if (recipeSlot.getItem().isEmpty()) {
                                recipeSlot.set(invSlot.getItem().copyWithCount(1));
                                invSlot.getItem().shrink(1);
                                break;
                            }
                        }
                    }
                }
            });
        }

@Override
        public IMessage onMessage(final MessageCasterOrb message, final MessageContext ctx) {
            EntityPlayer player = ctx.getServerHandler().player;
            WorldServer world = ctx.getServerHandler().player.getServerWorld();
            world.addScheduledTask(() -> {
                ItemStack heldStack = player.getHeldItemMainhand();
                if (ItemModUtil.hasHeat(heldStack)) {
                    int level = ItemModUtil.getModifierLevel(heldStack, EmbersAPI.CASTER_ORB);
                    UUID uuid = player.getUniqueID();
                    if (level > 0 && EmberInventoryUtil.getEmberTotal(player) > EmbersAPI.CASTER_ORB.cost && !ModifierCasterOrb.hasCooldown(uuid)) {
                        float handmod = player.getPrimaryHand() == EnumHandSide.RIGHT ? 1.0f : -1.0f;
                        float offX = handmod * 0.5f * (float) Math.sin(Math.toRadians(-player.rotationYaw - 90));
                        float offZ = handmod * 0.5f * (float) Math.cos(Math.toRadians(-player.rotationYaw - 90));
                        EmberInventoryUtil.removeEmber(player, EmbersAPI.CASTER_ORB.cost);
                        double lookDist = Math.sqrt(message.lookX * message.lookX + message.lookY * message.lookY + message.lookZ * message.lookZ);
                        if (lookDist == 0)
                            return;
                        double xVel = (message.lookX / lookDist) * 0.5;
                        double yVel = (message.lookY / lookDist) * 0.5;
                        double zVel = (message.lookZ / lookDist) * 0.5;
                        double xOrigin = player.posX + offX;
                        double yOrigin = player.posY + player.getEyeHeight();
                        double zOrigin = player.posZ + offZ;

                        double resonance = EmbersAPI.getEmberEfficiency(heldStack);
                        double value = 8.0 * (Math.atan(0.6 * (level)) / (1.25));
                        value *= resonance;
                        EffectDamage effect = new EffectDamage((float) value, DamageEmber.EMBER_DAMAGE_SOURCE_FACTORY, 1, 1.0);
                        ProjectileFireball fireball = new ProjectileFireball(player, new Vec3d(xOrigin, yOrigin, zOrigin), new Vec3d(xVel, yVel, zVel), value, 160, effect);
                        EmberProjectileEvent event = new EmberProjectileEvent(player, heldStack, 0.0, fireball);
                        MinecraftForge.EVENT_BUS.post(event);
                        if (!event.isCanceled()) {
                            for (IProjectilePreset projectile : event.getProjectiles()) {
                                projectile.shoot(world);
                            }
                        }
                        world.playSound(null, xOrigin, yOrigin, zOrigin, SoundManager.FIREBALL, SoundCategory.PLAYERS, 1.0f, 1.0f);
                        ModifierCasterOrb.setCooldown(uuid, 20);
                    }
                }
            });
            return null;
        }

public static void handle(MessageDragonControl message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            Player player = context.get().getSender();
            if(context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT){
                player = IceAndFire.PROXY.getClientSidePlayer();
