public static void handle(PacketRandomize message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      var player = ctx.player();

      Level world = player.getCommandSenderWorld();
      ItemStack held = player.getItemInHand(message.hand);
      IEnergyStorage storage = CapabilityUtil.energy(held);
      final int cost = RandomizerItem.COST.get();
      if (storage == null || storage.extractEnergy(cost, true) < cost) {
        return;
      }
      List<BlockPos> places = RandomizerItem.getPlaces(message.pos, message.side, held);
      List<BlockPos> rpos = new ArrayList<BlockPos>();
      List<BlockState> rstates = new ArrayList<BlockState>();
      //
      BlockState stateHere;
      for (BlockPos p : places) {
        stateHere = world.getBlockState(p);
        boolean canMove = RandomizerItem.canMove(stateHere, world, p);

        if (canMove) {
          //removed world.isSideSolid(p, message.side) && as it was blocking stairs/slabs from moving
          rpos.add(p);
          rstates.add(stateHere);
        }
      }
      Collections.shuffle(rpos, RND);
      BlockPos swapPos;
      BlockState swapState;
      synchronized (rpos) { //just in case
        for (int i = 0; i < rpos.size(); i++) {
          if (storage.extractEnergy(cost, true) < cost) {
            break;
          }
          swapPos = rpos.get(i);
          swapState = rstates.get(i);
          world.destroyBlock(swapPos, false);
          //playing sound here in large areas causes ConcurrentModificationException
          if (BlockUtil.placeStateSafe(world, player, swapPos, swapState, false)) {
            storage.extractEnergy(cost, false);
          }
        }
      }
    });
  }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            if (ctx.player().level().isClientSide())
                return;

            ServerPlayer player = (ServerPlayer) ctx.player();

            if (player.containerMenu.containerId != container) {
                causeError(player);

                return;
            }

            ItemStack stack = DescriptionUtils.gatherRelicStack(player, slot);

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                causeError(player);

                return;
            }

            RandomSource random = player.getRandom();

            switch (operation) {
                case ADD -> {
                    relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().addLink(from, to);

                    if (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().isComplete()) {
                        relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().setResearched(true);

                        player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.FINISH_RESEARCH.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 0.75F, 1F, random.nextLong()));
                    } else
                        player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.CONNECT_STARS.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 0.75F, 0.75F + random.nextFloat() * 0.5F, random.nextLong()));
                }
                case REMOVE -> relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().removeLink(from, to);
            }

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

@Override
	public void process(IPayloadContext context)
	{
		if(context.flow().getReceptionSide()==LogicalSide.SERVER)
		{
			ServerPlayer player = IMessage.serverPlayer(context);
			UUID playerId = player.getUUID();
			context.enqueueWork(() -> {
				if(key==MessageType.SYNC)
				{
					ResourceLocation[] ss = ShaderRegistry.receivedShaders.get(playerId).stream().filter(Objects::nonNull).toArray(ResourceLocation[]::new);
					PacketDistributor.sendToPlayer(player, new MessageShaderManual(MessageType.SYNC, ss));
				}
				else if(key==MessageType.UNLOCK&&!args.isEmpty())
				{
					ShaderRegistry.receivedShaders.put(playerId, args.get(0));
				}
				else if(key==MessageType.SPAWN&&!args.isEmpty())
				{
					if(!player.getAbilities().instabuild)
						// TODO should we check that this actually passed?
						IngredientUtils.consumePlayerIngredient(player, ShaderRegistry.shaderRegistry.get(args.get(0)).replicationCost.get());
