public static void handle(PacketContext<ServerboundSyncPatternPacket> context) {
		ServerPlayer player = context.sender();
		List<Pattern> pattern = context.message().patterns();

		ArcanusComponents.setPattern(player, pattern);

		if(pattern.size() >= 3 && context.message().castSpell()) {
			ItemStack stack = player.getMainHandItem();

			if(stack.getItem() instanceof StaffItem staff) {
				Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(player);

				if(optional.isPresent()) {
					ItemStack spellBook = ArcanusHelper.getActiveSpellBook(player);
					SpellBookComponent spells = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
					int index = ArcanusHelper.getSpellIndex(pattern);

					if(player.getCooldowns().getCooldownPercent(staff, 1f) == 0) {
						Spell spell = spells.getSpell(index);

						if(!spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).allMatch(spellComponent -> ArcanusComponents.knowsSpellComponents(player, spellComponent))) {
							player.displayClientMessage(Component.translatable(SPELL_UNKNOWN_SPELL_COMPONENTS).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
							return;
						}

						if(spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).count() > ArcanusComponents.maxSpellSize()) {
							player.displayClientMessage(Component.translatable(SPELL_TOO_MANY_COMPONENTS), true);
							return;
						}

						for(PrimalArcana primalArcana : spell.getArcanaCost().keySet()) {
							if(!player.isCreative() && !ArcanusComponents.drainArcana(player, primalArcana, spell.getArcanaCost().getDouble(primalArcana), false)) {
								player.displayClientMessage(Component.translatable(SPELL_NOT_ENOUGH_MANA).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
								return;
							}
						}

						ArcanusComponents.setPattern(player, ArcanusHelper.getSpellPattern(index));
						ArcanusComponents.setLastCastTime(player, player.level().getGameTime());
						spell.cast(player, player.serverLevel(), stack);
						player.displayClientMessage(Component.translatable(spell.getName()).withStyle(ChatFormatting.GREEN), true);

						for(Holder<Item> holder : BuiltInRegistries.ITEM.getTagOrEmpty(ArcanusItemTags.STAVES))
							player.getCooldowns().addCooldown(holder.value(), (int) (spell.getCoolDown() * player.getAttributeValue(ArcanusAttributes.SPELL_COOL_DOWN.holder())));
					}
				}
			}
		}
	}

public static void consume(CStopAttackPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            ServerPlayer playerEntity = ctx.get().getSender();

            if (playerEntity != null) {
                if (playerEntity.level instanceof ServerLevel serverLevel){
                    for (Entity entity : serverLevel.getAllEntities()){
                        if (entity instanceof IOwned owned && entity instanceof Mob mob && owned.getTrueOwner() == playerEntity){
                            Entity pick = MobUtil.getSingleTarget(serverLevel, playerEntity, 16, 3);
                            if (pick instanceof LivingEntity target
                                    && target != mob
                                    && target != owned.getTrueOwner()
                                    && !MobUtil.areAllies(playerEntity, target)
                                    && mob.distanceTo(playerEntity) <= 32){
                                mob.setTarget(target);
                                if (mob.getLastHurtByMob() != target){
                                    mob.setLastHurtByMob(target);
                                }
                                entity.playSound(ModSounds.ROAR_SPELL.get(), 0.5F, 2.0F);
                                owned.onStopAttack();
                            } else {
                                owned.onCeaseFire(playerEntity);
                                if (mob.getTarget() != null) {
                                    mob.setTarget(null);
                                    if (mob.getLastHurtByMob() != null){
                                        mob.setLastHurtByMob(null);
                                    }
                                    if (playerEntity.getLastHurtMob() != null) {
                                        playerEntity.setLastHurtMob(null);
                                    }
                                    if (mob.getBrain() != null) {
                                        mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                                        mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                                        mob.getBrain().eraseMemory(MemoryModuleType.HURT_BY);
                                    }
                                    if (mob instanceof NeutralMob neutralMob) {
                                        neutralMob.setPersistentAngerTarget(null);
                                        neutralMob.stopBeingAngry();
                                    }
                                    mob.setAggressive(false);
                                    entity.playSound(ModSounds.CAST_SPELL.get(), 1.0F, 1.0F);
                                    owned.onStopAttack();
                                }
                            }
                        }
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

public void handleDestroyPacket(final CPacketDestroy data, final IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      Player player = ctx.player();
      CuriosApi.getCuriosInventory(player)
          .ifPresent(handler -> handler.getCurios().values().forEach(stacksHandler -> {
            IDynamicStackHandler stackHandler = stacksHandler.getStacks();
            IDynamicStackHandler cosmeticStackHandler = stacksHandler.getCosmeticStacks();
            String id = stacksHandler.getIdentifier();

            for (int i = stackHandler.getSlots() - 1; i >= 0; i--) {
              NonNullList<Boolean> renderStates = stacksHandler.getRenders();
              SlotContext slotContext = new SlotContext(id, player, i, false,
                                                        renderStates.size() > i && renderStates.get(
                                                            i));
              ItemStack stack = stackHandler.getStackInSlot(i);
              ICurioItem
                  .forEachModifier(stack, slotContext,
                                   (attributeHolder, attributeModifier) -> {
                                     if (attributeHolder.value() instanceof SlotAttribute slotAttribute) {
                                       handler.removeSlotModifier(
                                           slotAttribute.id(),
                                           attributeModifier.id());
                                     } else {
                                       AttributeInstance instance =
                                           player.getAttributes().getInstance(attributeHolder);

                                       if (instance != null) {
                                         instance.removeModifier(attributeModifier);
                                       }
                                     }
                                   });
              CuriosApi.getCurio(stack)
                  .ifPresent(curio -> curio.onUnequip(slotContext, stack));
              stackHandler.setStackInSlot(i, ItemStack.EMPTY);
              PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                   new SPacketSyncStack(
                                                                       player.getId(), id, i,
                                                                       ItemStack.EMPTY,
                                                                       SPacketSyncStack.HandlerType.EQUIPMENT.ordinal(),
                                                                       new CompoundTag()));
              cosmeticStackHandler.setStackInSlot(i, ItemStack.EMPTY);
              PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                   new SPacketSyncStack(
                                                                       player.getId(), id, i,
                                                                       ItemStack.EMPTY,
                                                                       SPacketSyncStack.HandlerType.COSMETIC.ordinal(),
                                                                       new CompoundTag()));
            }
          }));
    });
  }

private void recheckConnectionPrechecked(Direction side) {
        TileEntityTransmitter otherTile = WorldUtils.getTileEntity(TileEntityTransmitter.class, getLevel(), getBlockPos().relative(side));
        if (otherTile != null) {
            NETWORK network = getTransmitterNetworkNN();
            //The other one should always have the same incompatible networks state as us
            // But just in case it doesn't just check the boolean
            Transmitter<?, ?, ?> other = otherTile.getTransmitter();
            if (other instanceof BufferedTransmitter && ((BufferedTransmitter<?, ?, ?, ?>) other).canHaveIncompatibleNetworks() && other.hasTransmitterNetwork()) {
                NETWORK otherNetwork = (NETWORK) other.getTransmitterNetworkNN();
                if (network != otherNetwork && network.isCompatibleWith(otherNetwork)) {
                    //We have two networks that are now compatible, and they are not the same source network
                    // The most common cause that they would be same source network is that they would merge
                    // from the first pipe checking when it attempts to reconnect, and then the second
                    // pipe still is going to be checking the connection.

                    if (noBufferOrFallback()) {
                        //If we don't have any use them as primary network
                        NETWORK tempNetwork = network;
                        network = otherNetwork;
                        otherNetwork = tempNetwork;
                    }

                    // Manually merge the networks.
                    // This code is not in network registry as there is special handling needed to ensure
                    // it visually updates properly. There also were above checks that get us to a certain
                    // point where we can make some assumptions about the networks and if it is actually
                    // valid to merge them when otherwise people may try to merge things when they shouldn't
                    // be merged causing unexpected bugs.
                    List<TRANSMITTER> otherTransmitters = network.adoptTransmittersAndAcceptorsFrom(otherNetwork);

                    //Unregister the other network
                    otherNetwork.deregister();
                    //Commit the changes of the new network
                    network.commit();

                    //We did not have these as part of the update because they got directly added
                    // This means that we have to update the buffer and queue client updates ourselves
                    network.clampBuffer();
                    //Recheck the connections
                    other.refreshConnections(side.getOpposite());
                    //Force all the newly merged transmitters to send a sync update to the client
                    // to ensure that they now have the proper network id on the client
                    // Note: adoptTransmittersAndAcceptorsFrom will return all the new transmitters except for
                    // those that already have our network as their network (which should be none of them)
                    for (TRANSMITTER otherTransmitter : otherTransmitters) {
                        otherTransmitter.requestsUpdate();
                    }
                }
            }
        }
    }

public static void handle(C2SChainedElectricityPacket packet, IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            if (!(ctx.player() instanceof ServerPlayer player) || player.level().isClientSide())
                return;

            var level = player.level();
            var position = new Vec3(packet.x, packet.y, packet.z);
            var slot = CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(packet.slotId, packet.slotIndex));

            if (slot.isEmpty())
                return;

            var stack = slot.get().stack();

            if (!(stack.getItem() instanceof KineticBeltItem))
                return;

            ChainedElectricityEntity previous = null;
            var previousId = stack.getOrDefault(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, -1);
            var bestDistance = Double.MAX_VALUE;

            if (previousId >= 0) {
                var raw = level.getEntity(previousId);

                if (raw instanceof ChainedElectricityEntity candidate && candidate.isAlive() && candidate.getOwner() == player) {
                    bestDistance = candidate.position().distanceToSqr(position);

                    if (bestDistance < 1D)
                        return;

                    if (bestDistance <= 100D)
                        previous = candidate;
                }
            }

            var electricity = new ChainedElectricityEntity(RelicsEntities.KINETIC_ELECTRICITY.get(), player.level());

            electricity.setLifetime(Math.max(1, packet.lifetime));
            electricity.setDamage(Math.max(0F, packet.damage));
            electricity.setFlawless(packet.flawless);
            electricity.setPos(position);
            electricity.setOwner(player);
            electricity.setStack(stack);

            if (previous != null && bestDistance <= 100D)
                electricity.setPreviousEntity(previous);

            level.addFreshEntity(electricity);

            stack.set(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, electricity.getId());
        });
    }

@Override
    public void handle(IPayloadContext context) {
        ServerPlayer player = (ServerPlayer) context.player();
        ItemStack stack = player.getItemInHand(currentHand);
        if (!stack.isEmpty() && stack.getItem() instanceof ItemPortableTeleporter) {
            TeleporterFrequency found = FrequencyTypes.TELEPORTER.getFrequency(identity, player.getUUID());
            if (found == null) {
                return;
            }
            GlobalPos coords = found.getClosestCoords(player.level().dimension(), player.blockPosition());
            if (coords != null) {
                ServerLevel teleWorld = player.level().getServer().getLevel(coords.dimension());
                TileEntityTeleporter teleporter = WorldUtils.getTileEntity(TileEntityTeleporter.class, teleWorld, coords.pos());
                if (teleporter != null) {
                    int energyCost;
                    try (Transaction transaction = Transaction.openRoot()) {
                        if (MekanismUtils.isPlayingMode(player)) {
                            energyCost = TileEntityTeleporter.calculateEnergyCost(player, teleWorld, coords);
                            EnergyHandler energyHandler = AutomatedEnergyHandler.manual(Capabilities.ENERGY.getCapability(ItemAccessUtils.playerHandAccess(player, currentHand)));
                            if (energyHandler == null || energyHandler.extract(energyCost, transaction) < energyCost) {
                                //Fail if there is not enough energy available
                                return;
                            }
                        } else {
                            energyCost = 0;
                        }
                        teleporter.didTeleport.add(player.getUUID());
                        teleporter.teleDelay = 5;
                        BlockPos teleporterTargetPos = teleporter.getTeleporterTargetPos();
                        MekanismTeleportEvent.PortableTeleporter event = new MekanismTeleportEvent.PortableTeleporter(player, teleporterTargetPos, teleWorld, stack, energyCost);
                        if (NeoForge.EVENT_BUS.post(event).isCanceled()) {
                            //Fail if the event was cancelled
                            return;
                        }
                        //Commit the energy usage
                        transaction.commit();
                        player.connection.aboveGroundTickCount = 0;
                        player.closeContainer();
                        PacketUtils.sendToAllTracking(new PacketPortalFX(player.blockPosition()), player.level(), coords.pos());
                        if (player.isPassenger()) {
                            player.stopRiding();
                        }
                        double oldX = player.getX();
                        double oldY = player.getY();
                        double oldZ = player.getZ();
                        Level oldWorld = player.level();
                        TileEntityTeleporter.teleportEntityTo(player, teleWorld, teleporter, event, false, TeleportTransition.DO_NOTHING);
                        if (player.level() != oldWorld || player.distanceToSqr(oldX, oldY, oldZ) >= 25) {
                            //If the player teleported over 5 blocks, play the sound at both the destination and the source
                            oldWorld.playSound(null, oldX, oldY, oldZ, SoundEvents.PLAYER_TELEPORT, SoundSource.PLAYERS);
                        }
                        player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_TELEPORT, SoundSource.PLAYERS);
                        teleporter.sendTeleportParticles();
                    }
                }
            }
        }
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            if (player.containerMenu.containerId != this.getContainer()) {
                this.causeError(player);

                return;
            }

            var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                this.causeError(player);

                return;
            }

            var abilitiesData = relic.getRelicData(player, stack).getAbilitiesData();
            AbilityTargetingTemplate targeting = null;

            if (this.isSynergy()) {
                var template = abilitiesData.getSynergyData(this.getTarget()).getTemplate();

                targeting = template == null ? null : template.getTargeting();
            } else {
                var template = abilitiesData.getAbilityData(this.getTarget()).getTemplate();

                targeting = template == null ? null : template.getTargeting();
            }

            if (targeting == null || !targeting.isActive()) {
                this.causeError(player);

                return;
            }

            AbilityTargetingOption option;
            SelectorType selectorType;

            try {
                selectorType = SelectorType.valueOf(this.getSelector().toUpperCase(Locale.ROOT));
                option = AbilityTargetingOption.valueOf(this.getOption().toUpperCase(Locale.ROOT));
            } catch (IllegalArgumentException exception) {
                this.causeError(player);

                return;
            }

            if (!targeting.hasOption(selectorType, option)) {
                this.causeError(player);

                return;
            }

            if (this.isSynergy())
                abilitiesData.getSynergyData(this.getTarget()).getTargetingData().setOption(option, selectorType, this.isValue());
            else
                abilitiesData.getAbilityData(this.getTarget()).getTargetingData().setOption(option, selectorType, this.isValue());
        });
    }

