                    boolean result = false;

                    if (withShift)
                        while (abilityData.calculateQuality() != abilityData.getMaxQuality() && abilityData.reroll())
                            result = true;
                    else
                        result = abilityData.reroll();

                    yield result;
                }
                case RESET -> abilityData.reset();
            }) return;

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

@Override
    public void tickClient(ICommonArmorHandler armorHandler, boolean isEnabled) {
        if (!isEnabled) return;

        int rangeUpgrades = armorHandler.getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.RANGE.get());
        Player player = armorHandler.getPlayer();

        // check for filter change and recompile filter if necessary
        ItemStack helmetStack = player.getItemBySlot(EquipmentSlot.HEAD);
        String filterStr = helmetStack.isEmpty() ? "" : PneumaticArmorItem.getEntityFilter(helmetStack);
        if (!entityFilter.toString().equals(filterStr)) {
            EntityFilter newFilter = EntityFilter.fromString(filterStr);
            if (newFilter != null) {
                entityFilter = newFilter;
            }
        }

        // find applicable entities and create/update render targets for them as needed
        double entityTrackRange = ENTITY_TRACKING_RANGE + rangeUpgrades * PneumaticValues.RANGE_UPGRADE_HELMET_RANGE_INCREASE_ENTITY;
        AABB bbBox = getAABBFromRange(player, rangeUpgrades);
        List<Entity> entities = armorHandler.getPlayer().level().getEntitiesOfClass(Entity.class, bbBox,
                new EntityTrackerSelector(player, entityFilter, entityTrackRange));
        for (Entity entity : entities) {
            RenderEntityTarget target = targets.get(entity.getId());
            if (target != null) {
                target.ticksExisted = Math.abs(target.ticksExisted); // cancel lost targets
            } else {
                targets.put(entity.getId(), new RenderEntityTarget(entity));
            }
        }

        // prune no-longer-applicable entities from the render target list
        IntList toRemove = new IntArrayList();
        targets.forEach((entityId, target) -> {
            if (!target.entity.isAlive() || player.distanceTo(target.entity) > entityTrackRange + 5 || !entityFilter.test(target.entity)) {
                if (target.ticksExisted > 0) {
                    target.ticksExisted = -60;
                } else if (target.ticksExisted == -1) {
                    toRemove.add(entityId.intValue());
                }
            }
        });
        toRemove.forEach(targets::remove);

        // handle tick logic for every valid render target
        List<Component> text = new ArrayList<>();
        for (RenderEntityTarget target : targets.values()) {
            boolean wasNegative = target.ticksExisted < 0;
            target.ticksExisted += armorHandler.getSpeedFromUpgrades(EquipmentSlot.HEAD);
            if (target.ticksExisted >= 0 && wasNegative) target.ticksExisted = -1;
            target.tick();
            if (target.isLookingAtTarget) {
                if (target.isInitialized()) {
                    text.add(target.entity.getDisplayName().copy().withStyle(ChatFormatting.GRAY));
                    text.addAll(target.getEntityText());
                } else {
                    text.add(xlate("pneumaticcraft.entityTracker.info.acquiring").withStyle(ChatFormatting.GRAY));
                }
            }
        }
        if (text.isEmpty()) {
            String f = entityFilter.toString();
            text.add(xlate("pneumaticcraft.gui.entityFilter").append(": " + (f.isEmpty() ? "-" : f)));
        }
        entityTrackInfo.setText(text);
    }

public static void handle(PacketSwapBlock message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {

      var player = ctx.player();
      ItemStack itemStackHeld = player.getItemInHand(message.hand);
      BlockState targetState = BuilderActionType.getBlockState(player.level(), itemStackHeld);
      if (targetState == null || itemStackHeld.getItem() instanceof BuilderItem == false) {
        return;
      }
      BuildStyle buildStyle = ((BuilderItem) itemStackHeld.getItem()).style;
      Level world = player.getCommandSenderWorld();
      IEnergyStorage storage = CapabilityUtil.energy(itemStackHeld);
      final int cost = BuilderItem.COST.get();
      if (storage == null || storage.extractEnergy(cost, true) < cost) {
        return;
      }
      BlockState replacedBlockState;
      List<BlockPos> places = getSelectedBlocks(world, message.pos, message.actionType, message.side, buildStyle);
      Map<BlockPos, Integer> processed = new HashMap<BlockPos, Integer>();
      BlockPos curPos;
      synchronized (places) {
        for (Iterator<BlockPos> i = places.iterator(); i.hasNext();) {
          curPos = i.next();
          if (storage.extractEnergy(cost, true) < cost) {
            break;
          }
          if (processed.containsKey(curPos) == false) {
            processed.put(curPos, 0);
          }
          if (processed.get(curPos) > 0) {
            continue; //dont process the same location more than once per click
          }
          processed.put(curPos, processed.get(curPos) + 1);
          int slot = PlayerUtil.getFirstSlotWithBlock(player, targetState);
          if (slot < 0) {
            //nothign found. is that ok?
            if (!player.isCreative()) {
              ChatUtil.sendStatusMessage(player, "scepter.cyclic.empty");
              break;
              //you have no materials left
            }
          }
          if (world.getBlockEntity(curPos) != null) {
            continue;
            //ignore tile entities IE do not break chests / etc
          }
          replacedBlockState = world.getBlockState(curPos);
          Block replacedBlock = replacedBlockState.getBlock();
          boolean isInBlacklist = false;
          //          for (String s : ItemBuildSwapper.swapBlacklist) {//dont use .contains on the list. must use .equals on string
          //            if (s != null && s.equals(itemName)) {
          //              isInBlacklist = true;
          //              break;
          //            }
          //          }
          if (isInBlacklist) {
            continue;
          }
          if (replacedBlockState.getDestroySpeed(world, curPos) < 0) {
            continue; //since we know -1 is unbreakable
          }
          //wait, do they match? are they the same? do not replace myself
          if (LevelWorldUtil.doBlockStatesMatch(replacedBlockState, targetState)) {
            continue;
          }
          //break it and drop the whatever
          //the destroy then set was causing exceptions, changed to setAir // https://github.com/PrinceOfAmber/Cyclic/issues/114
          world.setBlock(curPos, Blocks.AIR.defaultBlockState(), 0);
          boolean success = false;
          //place item block gets slabs in top instead of bottom. but tries to do facing stairs
          // success = UtilPlaceBlocks.placeItemblock(world, curPos, stackBuildWith, player);
          if (!success) {
            success = BlockUtil.placeStateSafe(world, player, curPos, targetState);
          }
          if (success) {
            storage.extractEnergy(cost, false);
            PlayerUtil.decrStackSize(player, slot);
            world.levelEvent(2001, curPos, Block.getId(targetState));
            //always break with PLAYER CONTEXT in mind
            replacedBlock.playerDestroy(world, player, curPos, replacedBlockState, null, itemStackHeld);
          }
        } // close off the for loop
      }
    });
  }

