        super.tick();

        Sponge.server().streamOnlinePlayers().forEach(player -> {
            try (final EntityTickContext context = TickPhase.Tick.ENTITY.createPhaseContext(PhaseTracker.SERVER).source(player)) {
                context.buildAndSwitch();
